import type { Lang } from './ui';
import { allFaqs } from './faqs-all';

export const faqTranslations: Record<Lang, Record<string, string>> = {
  en: {},
  es: {
    "How is a mortgage payment calculated?": "¿Cómo se calcula el pago de una hipoteca?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "El pago hipotecario mensual estándar se compone de Capital e Intereses (P&I), impuestos sobre la propiedad, seguro de hogar, seguro hipotecario privado (PMI) si el pago inicial es inferior al 20%, y cuotas de comunidad (HOA).",
    "What is PMI and when do I pay it?": "¿Qué es el PMI y cuándo se paga?",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "El Seguro Hipotecario Privado (PMI) protege al prestamista en caso de impago. Generalmente se exige en préstamos convencionales si la entrada es inferior al 20% del precio de la vivienda.",
    "What does PITI stand for?": "¿Qué significa PITI?",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI significa Capital (Principal), Intereses, Impuestos (Taxes) y Seguros (Insurance). Son los cuatro componentes clave de la cuota mensual de una vivienda.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "¿Es mejor una hipoteca a 15 años que una a 30 años?",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "Una hipoteca a 15 años ofrece un tipo de interés más bajo y amortiza el inmueble el doble de rápido, ahorrando miles en intereses. Sin embargo, a 30 años la mensualidad es menor, ofreciendo mayor liquidez mes a mes.",
    "How do extra payments affect my mortgage payoff schedule?": "¿Cómo afectan los pagos adicionales al calendario de la hipoteca?",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Todo pago adicional amortiza directamente el capital principal. Esto reduce el saldo pendiente y los intereses futuros, permitiendo liquidar la hipoteca años antes y ahorrando gran cantidad de dinero.",
    "What is the Debt Snowball method?": "¿Qué es el método Bola de Nieve?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "El método Bola de Nieve consiste en liquidar primero las deudas de menor saldo, sin importar su tasa de interés. Proporciona impulso psicológico mediante victorias rápidas.",
    "What is the Debt Avalanche method?": "¿Qué es el método Avalancha?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "El método Avalancha liquida primero las deudas con la tasa de interés más alta. Matemáticamente minimiza el interés total pagado y acelera el fin de las deudas.",
    "Which method is better: Debt Snowball or Debt Avalanche?": "¿Cuál es mejor: Bola de Nieve o Avalancha?",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Matemáticamente, la Avalancha es superior al minimizar intereses. Sin embargo, la Bola de Nieve suele tener mayor éxito práctico porque las victorias tempranas motivan a perseverar.",
    "How does the 'extra payment' roll over in these strategies?": "¿Cómo se transfiere el 'pago extra' en estas estrategias?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "En ambos métodos pagas el mínimo en todas las deudas y concentras el excedente en la deuda objetivo. Al liquidarla, transfieres todo ese monto mensual a la siguiente deuda.",
    "Can I do a hybrid of Snowball and Avalanche?": "¿Puedo hacer un híbrido entre Bola de Nieve y Avalancha?",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Sí. Puedes pagar una o dos deudas pequeñas al principio para liberar flujo de caja (Bola de Nieve) y luego liquidar las restantes por tasa de interés más alta (Avalancha).",
    "When should I refinance my loan?": "¿Cuándo conviene refinanciar un préstamo?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Conviene refinanciar si obtienes una tasa menor, reduces la cuota o acortas el plazo, siempre que el ahorro en intereses supere los gastos de cierre.",
    "What closing costs are associated with refinancing?": "¿Qué costes de cierre conlleva la refinanciación?",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Incluyen costes de estudio, tasación, gestoría, registro y comisiones, que suelen oscilar entre el 2% y el 6% del importe solicitado.",
    "How do I calculate my refinance break-even point?": "¿Cómo calculo el punto de equilibrio de la refinanciación?",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Divide los costes totales de cierre entre el ahorro mensual obtenido. Por ejemplo, $3.000 de gastos / $150 de ahorro = 20 meses de amortización del gasto.",
    "What is the 28/36 rule?": "¿Qué es la regla 28/36?",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "Establece que el gasto mensual en vivienda no debe superar el 28% de los ingresos brutos, y las deudas totales no deben exceder el 36%.",
    "How does DTI affect my mortgage application?": "¿Cómo influye el DTI en la solicitud de hipoteca?",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Los bancos usan la relación deuda-ingreso (DTI) para medir el riesgo crediticio. Un DTI inferior al 36% se considera óptimo y de bajo riesgo.",
    "What is the difference between front-end and back-end DTI?": "¿Cuál es la diferencia entre el DTI inicial y el DTI total?",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "El DTI inicial considera solo gastos de vivienda (hipoteca, impuestos, seguros). El DTI total incluye la vivienda más todas las demás obligaciones mensuales recurrentes.",
    "How can I lower my Debt-to-Income ratio?": "¿Cómo puedo reducir mi ratio Deuda-Ingreso?",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Aumentando tus ingresos brutos o amortizando deudas recurrentes para eliminar sus cuotas mínimas mensuales del cómputo.",
    "What is the SAVE plan?": "¿Qué es el plan SAVE?",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "Es un plan de pago de préstamos estudiantiles vinculado a los ingresos. Protege el 225% del umbral de pobreza, reduce pagos y evita que se acumulen intereses impagados.",
    "How is discretionary income calculated for student loans?": "¿Cómo se calcula el ingreso disponible para préstamos estudiantiles?",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "Es la diferencia entre tus ingresos brutos ajustados y el porcentaje de la línea de pobreza según el número de miembros de tu familia.",
    "How do I calculate stock returns?": "¿Cómo calculo la rentabilidad de las acciones?",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Resta el precio de compra al de venta para hallar la plusvalía, suma los dividendos recibidos, divide entre el precio de compra y multiplica por 100.",
    "What is CAGR in stock returns?": "¿Qué es el CAGR en inversiones bursátiles?",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "Es la Tasa de Crecimiento Anual Compuesto. Representa la rentabilidad anualizada geométrica obtenida a lo largo de un período.",
    "What is the Capital Asset Pricing Model (CAPM)?": "¿Qué es el Modelo CAPM?",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "Es un modelo financiero que calcula la rentabilidad esperada de un activo en función de su riesgo sistemático (Beta) frente al mercado.",
    "What does Asset Beta (β) represent?": "¿Qué representa la Beta (β) de un activo?",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "Mide la volatilidad o riesgo sistemático respecto al mercado general. Beta = 1 se mueve con el mercado; Beta > 1 implica mayor volatilidad y riesgo.",
    "What is net worth?": "¿Qué es el patrimonio neto?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "Es el valor monetario de todo lo que posees (activos) menos todo lo que debes (pasivos). Es la métrica fundamental de salud financiera.",
    "How much emergency fund is recommended?": "¿Cuánto dinero se recomienda en un fondo de emergencia?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "La mayoría de expertos aconseja ahorrar entre 3 y 6 meses de gastos básicos imprescindibles. Si tus ingresos son variables, conviene aspirar a 9 o 12 meses.",
    "What is an expense ratio?": "¿Qué es el ratio de gastos (Expense Ratio)?",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "Es la comisión anual que cobra un fondo de inversión o ETF por su gestión, expresada como porcentaje del capital invertido.",
    "What is Dollar-Cost Averaging (DCA)?": "¿Qué es el Dollar-Cost Averaging (DCA)?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "Consiste en invertir una suma fija de forma periódica (semanal o mensual) sin importar el precio, reduciendo la volatilidad y el riesgo de mercado.",
    "What is inflation?": "¿Qué es la inflación?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "Es el aumento generalizado de precios y la consiguiente pérdida del poder adquisitivo del dinero a lo largo del tiempo.",
    "What is the key difference between a Roth and Traditional IRA?": "¿Cuál es la diferencia clave entre una cuenta Tradicional y una tipo Roth?",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "Las aportaciones tradicionales reducen la base imponible hoy pero tributan al jubilarse. Las cuentas tipo Roth se aportan en neto y se rescatan 100% libres de impuestos.",
    "How does debt consolidation save you money?": "¿Cómo ahorra dinero la consolidación de deudas?",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "La consolidación agrupa múltiples deudas con altos intereses (como tarjetas de crédito al 20%–29% TAE) en un único préstamo personal con un tipo fijo menor (ej. 8%–14% TAE). Esto reduce tu pago mensual total y ahorra miles de dólares o euros en intereses.",
    "Does debt consolidation hurt your credit score?": "¿Afecta la consolidación de deudas a tu calificación crediticia?",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "Solicitar un nuevo préstamo causa una pequeña bajada temporal por la consulta de crédito. Sin embargo, cancelar las tarjetas saturadas reduce de inmediato tu ratio de utilización de crédito, lo que suele aumentar tu puntuación crediticia en un plazo de 30 a 60 días.",
    "What is the difference between debt consolidation and debt settlement?": "¿Cuál es la diferencia entre consolidación y liquidación de deudas?",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "La consolidación paga íntegramente a tus acreedores mediante un nuevo préstamo con menor interés sin dañar tu historial. La liquidación implica dejar de pagar para negociar quitas, lo que provoca daños graves y duraderos en tu informe crediticio.",
    "What should I look out for before consolidating debt?": "¿Qué precauciones debo tomar antes de consolidar deudas?",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Presta atención a las comisiones de apertura (normalmente entre el 1% y el 6%), asegúrate de que la nueva cuota mensual se ajuste cómodamente a tu presupuesto y evita endeudarte de nuevo en las tarjetas liquidadas.",
    "What is daily compound interest and how does it work?": "¿Qué es el interés compuesto diario y cómo funciona?",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "El interés compuesto diario calcula y añade los intereses generados al saldo cada día (365 veces al año). En los días siguientes, ganas intereses sobre el capital inicial y sobre los intereses acumulados previamente, acelerando el crecimiento exponencial del patrimonio.",
    "What is the formula for daily compound interest?": "¿Cuál es la fórmula del interés compuesto diario?",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "La fórmula es A = P(1 + r/365)^(365 × t), donde P es el capital inicial, r es la tasa anual (en decimal) y t es el tiempo en años. Al añadir depósitos periódicos, los intereses se calculan sobre el saldo diario acumulado.",
    "How much more money do you earn with daily vs monthly compounding?": "¿Cuánto más se gana con capitalización diaria frente a mensual?",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "En un depósito de 100.000 $ al 7% TAE a 20 años, la capitalización diaria produce 405.514 $ frente a 403.873 $ de la mensual, lo que genera 1.641 $ adicionales únicamente por la mayor frecuencia de capitalización.",
    "Do high-yield savings accounts (HYSA) compound daily?": "¿Las cuentas de ahorro de alto rendimiento generan interés compuesto diario?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Sí, la gran mayoría de cuentas de ahorro remuneradas y fondos monetarios capitalizan intereses diariamente y abonan el importe en tu saldo el último día hábil de cada mes.",
    "What is the FIRE movement and what does it mean?": "¿Qué es el movimiento FIRE y qué significa?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE significa 'Independencia Financiera, Jubilación Temprana' (Financial Independence, Retire Early). Es una filosofía donde se maximiza la tasa de ahorro (a menudo del 40% al 70%) y se invierte en fondos indexados hasta que la cartera genere suficientes ingresos pasivos para cubrir los gastos de por vida.",
    "What is the 4% Safe Withdrawal Rule?": "¿Qué es la regla del 4% de retiro seguro?",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Procedente del Estudio Trinity, la regla del 4% indica que puedes retirar el 4% del valor inicial de tu cartera al año (ajustado anualmente por inflación) con más del 95% de probabilidad de no agotar tus fondos durante una jubilación de 30 años.",
    "How is your FIRE Number calculated?": "¿Cómo se calcula tu Cifra FIRE?",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Tu cifra FIRE equivale a tus gastos anuales multiplicados por 25 (según la regla del 4%) o por 33 (con un enfoque conservador del 3%). Por ejemplo, si gastas 60.000 $ al año, tu cifra FIRE es de 1.500.000 $.",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "¿Cuál es la diferencia entre Lean FIRE, Standard FIRE y Fat FIRE?",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Lean FIRE cubre únicamente gastos esenciales y minimalistas (menos de 40.000 $/año). Standard FIRE sostiene un estilo de vida de clase media acomodada (50.000 $–100.000 $/año). Fat FIRE permite gastos de alto nivel y viajes de lujo (más de 120.000 $/año) sin restricciones financieras.",
    "When is the earliest age I can claim Social Security retirement benefits?": "¿Cuál es la edad mínima para solicitar los beneficios de jubilación de la Seguridad Social?",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "Puedes comenzar a recibir prestaciones de la Seguridad Social desde los 62 años. No obstante, solicitarlo anticipadamente reduce permanentemente tu mensualidad hasta un 30% en comparación con esperar a la Plena Edad de Jubilación (FRA).",
    "What is my Full Retirement Age (FRA)?": "¿Cuál es mi Plena Edad de Jubilación (FRA)?",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Para cualquier persona nacida en 1960 o después, la Plena Edad de Jubilación es a los 67 años. Si solicitas el beneficio a esa edad, recibes el 100% de la cantidad básica asignada sin penalizaciones por retiro anticipado.",
    "How much more do I get if I delay claiming Social Security until age 70?": "¿Cuánto más recibo si retraso la solicitud de la Seguridad Social hasta los 70 años?",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Por cada año que demores la solicitud más allá de tu edad reglamentaria (hasta los 70 años), tu pensión aumenta un 8% anual por créditos de jubilación postergada. Esperar hasta los 70 te otorga cerca del 124% de tu prestación total de forma vitalicia.",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "¿Cuál es la edad de equilibrio entre jubilarse a los 62 o a los 70 años?",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "La edad de equilibrio se sitúa habitualmente entre los 78 y los 81 años. Si estimas vivir más allá de los 80 años, retrasar la solicitud hasta los 70 produce casi siempre una retribución total acumulada superior a lo largo de la vida.",
    "What is the Australian Superannuation Guarantee (SG) rate?": "¿Cuál es la tasa de la Garantía de Superannuation (SG) australiana?",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "Por ley de la Commonwealth de Australia, los empleadores están obligados a aportar un porcentaje de tu salario ordinario a tu fondo de pensiones designado. La tasa está legislada para alcanzar el 12%.",
    "How is money inside Australian Super taxed?": "¿Cómo tributa el dinero dentro de un fondo Super australiano?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "Las aportaciones con ventajas fiscales (incluidas las patronales y el sacrificio salarial antes de impuestos) tributan a una tasa reducida del 15% dentro del fondo, frente a los tramos marginales del IRPF que pueden alcanzar el 45% más el gravamen de Medicare.",
    "How much super do I need for a comfortable retirement in Australia?": "¿Cuánto dinero en el fondo Super se necesita para una jubilación cómoda en Australia?",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Según el estándar de jubilación de la ASFA, una persona soltera necesita un saldo de aproximadamente 595.000 $ a los 67 años, mientras que una pareja requiere unos 690.000 $ para mantener un nivel de vida confortable durante el retiro.",
    "How does salary sacrificing boost superannuation growth?": "¿Cómo impulsa el crecimiento del fondo Super el sacrificio salarial (Salary Sacrifice)?",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "El sacrificio salarial permite transferir ingresos brutos antes de impuestos directamente al plan de pensiones. Al evitar tipos impositivos marginales más altos y aprovechar el interés compuesto durante décadas, puede sumar cientos de miles de dólares a tu fondo de jubilación."
  },
  de: {
    "How is a mortgage payment calculated?": "Wie wird eine monatliche Kreditrate berechnet?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "Eine Standardrate umfasst Tilgung und Zins sowie Grundsteuer, Gebäudeversicherung und ggf. Risikozuschläge bei geringem Eigenkapital.",
    "What is PMI and when do I pay it?": "Was ist eine Hypothekenversicherung (PMI)?",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "Eine Versicherung zum Schutz der Bank bei Zahlungsausfall, meist fällig bei Eigenkapital unter 20 %.",
    "What does PITI stand for?": "Wofür steht die Abkürzung PITI?",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI steht für Principal (Tilgung), Interest (Zinsen), Taxes (Grundsteuer) und Insurance (Gebäudeversicherung). Dies sind die vier Kernkomponenten der monatlichen Gesamtwohnkosten eines Immobilienbesitzers.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "Ist eine 15-jährige Zinsbindung besser als eine 30-jährige?",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "15 Jahre bieten günstigere Zinsen und schnellere Entschuldung, 30 Jahre bieten geringere Monatsraten und mehr finanziellen Spielraum.",
    "How do extra payments affect my mortgage payoff schedule?": "Wie wirken sich Sondertilgungen auf die Baufinanzierung aus?",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Jede Sondertilgung wird unmittelbar mit der verbleibenden Restschuld verrechnet. Dies senkt die künftige Zinsbelastung, verkürzt die Kreditlaufzeit oft um mehrere Jahre und spart beträchtliche Zinskosten.",
    "What is the Debt Snowball method?": "Was ist die Schneeball-Methode?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Das schnellstmögliche Tilgen kleinster Verbindlichkeiten zuerst, um schnelle Motivationserfolge zu feiern.",
    "What is the Debt Avalanche method?": "Was ist die Lawinen-Methode?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Das gezielte Tilgen der Kredite mit den höchsten Zinsen zuerst, um Zinskosten rechnerisch zu minimieren.",
    "Which method is better: Debt Snowball or Debt Avalanche?": "Welche Methode ist besser: Schneeball oder Lawine?",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Mathematisch ist die Lawinen-Methode überlegen, da sie durch Priorisierung der teuersten Zinsen die Gesamtkosten minimiert. In der Praxis ist die Schneeball-Methode jedoch oft erfolgreicher, weil schnelle Tilgungserfolge bei kleinen Krediten die Motivation aufrechterhalten.",
    "How does the 'extra payment' roll over in these strategies?": "Wie wird die freiwerdende Rate bei diesen Entschuldungsstrategien übertragen?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Bei beiden Methoden zahlen Sie zunächst die Mindestraten aller Kredite. Überschüssiges Budget fließt in den primären Fokuskredit. Sobald dieser getilgt ist, wird dessen gesamte Rate auf den nächsten Kredit übertragen – wie ein Schneeball, der anwächst.",
    "Can I do a hybrid of Snowball and Avalanche?": "Kann man Schneeball- und Lawinen-Methode kombinieren?",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Ja. Viele tilgen zuerst ein oder zwei kleine Kredite, um schnelle Erfolgserlebnisse zu verbuchen und monatlichen Cashflow freizusetzen (Schneeball), und wechseln danach zur Tilgung nach dem höchsten Zinssatz (Lawine).",
    "When should I refinance my loan?": "Wann lohnt sich eine Umschuldung oder Prolongation?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Eine Umschuldung lohnt sich in der Regel, wenn Sie einen spürbar niedrigeren Zinssatz erhalten, die monatliche Rate senken oder die Laufzeit verkürzen können – vorausgesetzt, die Zinsersparnis übersteigt eventuelle Vorfälligkeitsentschädigungen oder Wechselkosten.",
    "What closing costs are associated with refinancing?": "Welche Nebenkosten fallen bei einer Kreditumschuldung an?",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Mögliche Nebenkosten umfassen Bearbeitungsgebühren, Notar- und Grundbuchkosten für die Abtretung von Grundschulden sowie etwaige Vorfälligkeitsentschädigungen der bisherigen Bank. Sie betragen meist 1 % bis 3 % der Restsumme.",
    "How do I calculate my refinance break-even point?": "Wie berechnet man den Break-Even-Punkt einer Umschuldung?",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Teilen Sie die gesamten Umschuldungsnebenkosten durch die monatliche Ratenersparnis. Beispiel: Bei 1.500 € Nebenkosten und 75 € Ersparnis pro Monat ist der Break-Even nach 20 Monaten erreicht (1.500 € / 75 €).",
    "What is the 28/36 rule?": "Was ist die 28/36-Haushaltsregel?",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "Maximal 28 % des Bruttoeinkommens für Wohnen und maximal 36 % für sämtliche Schuldenverpflichtungen.",
    "How does DTI affect my mortgage application?": "Wie beeinflusst die Verschuldungsquote (DTI) die Kreditzusage?",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Banken nutzen das Verhältnis von Verbindlichkeiten zu Einkommen (DTI), um Ihre finanzielle Tragfähigkeit zu prüfen. Eine DTI unter 36 % gilt als risikoarm und erhöht die Chancen auf beste Konditionen deutlich.",
    "What is the difference between front-end and back-end DTI?": "Was ist der Unterschied zwischen Front-End- und Back-End-DTI?",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "Front-End-DTI berücksichtigt nur die reinen Wohnkosten (Kreditrate, Grundsteuer, Gebäudeversicherung). Back-End-DTI umfasst alle monatlichen Zahlungsverpflichtungen zusammen (Wohnen plus Ratenkredite, Kreditkarten und Unterhalt).",
    "How can I lower my Debt-to-Income ratio?": "Wie kann ich meine Verschuldungsquote (DTI) verbessern?",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Indem Sie Ihr Bruttoeinkommen steigern oder bestehende monatliche Verbindlichkeiten tilgen. Besonders das vollständige Abzahlen kleinerer Kredite senkt die monatliche Ratenlast sofort spürbar.",
    "What is the SAVE plan?": "Was ist der einkommensabhängige SAVE-Rückzahlungsplan?",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "Der SAVE-Plan ist ein US-Bundesmodell zur einkommensabhängigen Rückzahlung von Studienkrediten. Er schützt bis zu 225 % der Armutsgrenze als Freibetrag, deckelt Rückzahlungen und verhindert das Anwachsen nicht bezahlter Zinsen.",
    "How is discretionary income calculated for student loans?": "Wie wird das frei verfügbare Einkommen berechnet?",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "Das frei verfügbare Einkommen (Discretionary Income) ist die Differenz zwischen dem bereinigten Bruttoeinkommen (AGI) und einem gesetzlichen Freibetrag bezogen auf die Armutsgrenze der Haushaltsgröße.",
    "How do I calculate stock returns?": "Wie berechnet man die Aktienrendite?",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Ziehen Sie den Kaufpreis vom Verkaufspreis ab (Kursgewinn), addieren Sie alle erhaltenen Dividenden, teilen Sie das Ergebnis durch den Kaufpreis und multiplizieren Sie mit 100 für den prozentualen Ertrag.",
    "What is CAGR in stock returns?": "Was bedeutet CAGR bei Investitionen?",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "CAGR steht für Compound Annual Growth Rate (durchschnittliche jährliche Wachstumsrate). Sie beschreibt die geglättete jährliche Rendite einer Anlage über einen bestimmten Zeitraum unter Berücksichtigung des Zinseszinseffekts.",
    "What is the Capital Asset Pricing Model (CAPM)?": "Was ist das Capital Asset Pricing Model (CAPM)?",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "CAPM ist ein finanzmathematisches Bewertungsmodell, das die erwartete Rendite eines Wertpapiers anhand seines systematischen Marktrisikos (Beta) im Verhältnis zum risikofreien Zinssatz und der Marktrisikoprämie schätzt.",
    "What does Asset Beta (β) represent?": "Was drückt das Beta (β) einer Aktie aus?",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "Beta misst die Schwankungsbreite (Volatilität) eines Wertpapiers im Vergleich zum Gesamtmarkt. Ein Beta von 1,0 bedeutet marktkonforme Bewegung, über 1,0 höhere Volatilität und unter 1,0 geringere Kursschwankungen.",
    "What is net worth?": "Was ist das Reinvermögen (Net Worth)?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "Der Gesamtwert aller Vermögenswerte abzüglich sämtlicher Verbindlichkeiten und Schulden.",
    "How much emergency fund is recommended?": "Wie hoch sollte der Notgroschen sein?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "Empfohlen werden 3 bis 6 Monatsausgaben an lebensnotwendigen Kosten auf einem Tagesgeldkonto.",
    "What is an expense ratio?": "Was ist die Gesamtkostenquote (TER / Expense Ratio)?",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "Die Total Expense Ratio (TER) gibt die jährlichen Verwaltungskosten eines Fonds oder ETFs als Prozentsatz des investierten Vermögens an (z. B. 0,15 % = 1,50 € pro 1.000 € Anlagebetrag).",
    "What is Dollar-Cost Averaging (DCA)?": "Was ist der Durchschnittskosteneffekt (Cost-Average-Effekt)?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "Regelmäßiges Investieren fester Beträge zur Glättung von Kursschwankungen und Ausschaltung von Emotionen.",
    "What is inflation?": "Was ist Inflation?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "Der anhaltende Anstieg des allgemeinen Preisniveaus und der damit einhergehende Verlust der Kaufkraft.",
    "What is the key difference between a Roth and Traditional IRA?": "Was ist der Hauptunterschied zwischen nachgelagerter und sofortiger Besteuerung?",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "Bei traditionellen Vorsorgemodellen sind Einzahlungen sofort steuerlich absetzbar, Rentenauszahlungen im Alter jedoch voll einkommensteuerpflichtig. Bei Roth-Modellen erfolgt die Einzahlung aus versteuertem Einkommen, dafür sind Erträge und Auszahlungen im Ruhestand zu 100 % steuerfrei.",
    "How does debt consolidation save you money?": "Wie spart eine Umschuldung (Schuldenkonsolidierung) Geld?",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "Durch die Zusammenfassung mehrerer teurer Kredite (z. B. Dispositions- und Kreditkartenschulden mit 12 %–20 % Zinsen) in einem einzigen Ratenkredit mit niedrigerem Festzins (z. B. 5 %–8 %) sinkt die monatliche Rate und Sie sparen Tausende Euro an Zinskosten.",
    "Does debt consolidation hurt your credit score?": "Beeinträchtigt eine Kreditumschuldung die Bonität (Schufa)?",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "Die Kreditanfrage kann den Score kurzfristig minimal beeinflussen. Das Ablösen mehrerer offener Kreditlinien verbessert jedoch das Kreditauslastungsverhältnis, was die Bonität in der Regel binnen 1 bis 2 Monaten deutlich steigert.",
    "What is the difference between debt consolidation and debt settlement?": "Was unterscheidet Umschuldung von Schuldenvergleich oder Insolvenz?",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "Eine Umschuldung begleicht alle Forderungen vollständig über ein neues Darlehen ohne Bonitätsschaden. Ein Schuldenvergleich oder Erlassversuch stoppt Zahlungen, um Gläubiger zu Verzicht zu bewegen, was zu schweren, jahrelangen Bonitätseinträgen führt.",
    "What should I look out for before consolidating debt?": "Worauf sollte man vor einer Umschuldung achten?",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Achten Sie auf Bearbeitungskosten oder Vorfälligkeitsentschädigungen, stellen Sie sicher, dass die neue Monatsrate dauerhaft tragbar ist, und vermeiden Sie es, abbezahlte Kreditkarten oder Dispokredite erneut zu belasten.",
    "What is daily compound interest and how does it work?": "Was ist täglicher Zinseszins und wie funktioniert er?",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "Beim täglichen Zinseszins werden die Zinsen an jedem Tag (365 Mal im Jahr) berechnet und dem Guthaben zugeschlagen. An Folgetagen verzinst sich somit sowohl das Anfangskapital als auch der aufgelaufene Zinsgewinn, was das Vermögenswachstum exponentiell beschleunigt.",
    "What is the formula for daily compound interest?": "Wie lautet die mathematische Formel für täglichen Zinseszins?",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "Die Zinseszinsformel lautet A = P × (1 + r/365)^(365 × t), wobei P das Anfangskapital, r der Jahreszinssatz (als Dezimalzahl) und t die Anlagedauer in Jahren ist. Bei laufenden Sparraten wird der Zins täglich fortgeschrieben.",
    "How much more money do you earn with daily vs monthly compounding?": "Wie viel Mehrertrag bringt tägliche gegenüber monatlicher Verzinsung?",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "Bei einem Anlagebetrag von 100.000 € zu 7 % über 20 Jahre ergibt die tägliche Verzinsung 405.514 € gegenüber 403.873 € bei monatlicher Verzinsung – das sind 1.641 € reiner Mehrertrag nur durch die Zinsfrequenz.",
    "Do high-yield savings accounts (HYSA) compound daily?": "Verzinsen Tagesgeldkonten das Guthaben täglich?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Ja, die überwiegende Mehrheit der modernen Tagesgeldkonten und Geldmarktfonds verzinst das Guthaben taggenau (Valuta) und schreibt den Ertrag monatlich oder quartalsweise gut.",
    "What is the FIRE movement and what does it mean?": "Was bedeutet die FIRE-Bewegung?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE steht für 'Financial Independence, Retire Early' (Finanzielle Freiheit, früher Ruhestand). Ziel ist eine hohe Sparquote (40 %–70 %) und langfristiges Investieren in breit gestreute ETFs, bis das Vermögen alle Lebenshaltungskosten dauerhaft passiv deckt.",
    "What is the 4% Safe Withdrawal Rule?": "Was besagt die 4-%-Regel zur sicheren Entnahme?",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Basierend auf der renommierten Trinity-Studie besagt die 4-%-Regel, dass Sie jährlich 4 % Ihres Startportfolios (jährlich inflationsbereinigt) entnehmen können, mit einer Wahrscheinlichkeit von über 95 %, dass das Vermögen über einen 30-jährigen Ruhestand niemals aufgebraucht wird.",
    "How is your FIRE Number calculated?": "Wie wird die persönliche FIRE-Vermögenssumme berechnet?",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Die FIRE-Zahl entspricht Ihren jährlichen Ausgaben multipliziert mit 25 (bei einer Entnahmerate von 4 %) oder multipliziert mit 33 (bei konservativeren 3 %). Bei jährlichen Kosten von 48.000 € liegt das Zielvermögen bei 1.200.000 €.",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Was unterscheidet Lean FIRE, Standard FIRE und Fat FIRE?",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Lean FIRE zielt auf frugalen, minimalistischen Lebensstil mit niedrigen Ausgaben ab. Standard FIRE finanziert einen komfortablen bürgerlichen Lebensstandard. Fat FIRE erlaubt gehobenen Lebenskomfort, Reisen und Konsum ohne Budgetbeschränkungen.",
    "When is the earliest age I can claim Social Security retirement benefits?": "Ab welchem Alter ist ein vorzeitiger Rentenantritt möglich?",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "In Systemen wie der US Social Security ist der Renteneintritt ab 62 Jahren möglich, führt jedoch zu lebenslangen Abschlägen von bis zu 30 % gegenüber dem Erreichen der regulären Regelaltersgrenze.",
    "What is my Full Retirement Age (FRA)?": "Was ist das reguläre Renteneintrittsalter?",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Für Personen mit Geburtsjahrgang 1960 oder später liegt das reguläre Renteneintrittsalter bei 67 Jahren. Wer erst zu diesem Zeitpunkt in Rente geht, erhält 100 % der vollen Ansprüche ohne lebenslange Rentenkürzung.",
    "How much more do I get if I delay claiming Social Security until age 70?": "Wie viel höher fällt die Rente aus, wenn man den Ruhestand bis 70 aufschiebt?",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Für jedes Jahr des Hinausschiebens über das reguläre Rentenalter hinaus steigt der Rentenanspruch um ca. 8 % pro Jahr. Ein Rentenbeginn mit 70 Jahren sichert so dauerhaft rund 124 % der ursprünglichen Regelrente.",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "In welchem Alter liegt der Break-Even-Punkt zwischen Frührente und spätem Rentenbeginn?",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "Der lebenslange Break-Even-Punkt liegt typischerweise zwischen 78 und 81 Jahren. Wer älter als 80 wird, erzielt durch den aufgeschobenen Rentenbeginn eine deutlich höhere kumulierte Gesamtauszahlung.",
    "What is the Australian Superannuation Guarantee (SG) rate?": "Was ist die gesetzliche Rentenabgabe in Australien (Superannuation SG)?",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "Nach australischem Recht sind Arbeitgeber verpflichtet, einen gesetzlich festgelegten Prozentsatz des Bruttogehalts in den persönlichen Altersvorsorgefonds (Super) der Beschäftigten einzuzahlen. Der Satz steigt schrittweise auf 12 %.",
    "How is money inside Australian Super taxed?": "Wie wird das Vorsorgekapital im australischen Rentenfonds besteuert?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "Steuerbegünstigte Beiträge (einschließlich Arbeitgeberbeiträge und Gehaltsumwandlung) werden im Fonds pauschal mit nur 15 % versteuert – deutlich weniger als der persönliche Grenzsteuersatz von bis zu 45 %.",
    "How much super do I need for a comfortable retirement in Australia?": "Wie viel Vorsorgekapital wird für einen komfortablen Ruhestand benötigt?",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Nach dem ASFA-Altersvorsorgestandard benötigt ein Alleinstehender mit 67 Jahren ein Fondsguthaben von rund 595.000 AUD und ein Paar rund 690.000 AUD, um einen komfortablen Lebensstandard im Alter zu finanzieren.",
    "How does salary sacrificing boost superannuation growth?": "Wie beschleunigt die Entgeltumwandlung (Salary Sacrifice) den Vermögensaufbau?",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "Bei der Entgeltumwandlung fließen Gehaltsteile vor Steuern direkt in die Altersvorsorge. Durch die Ersparnis beim persönlichen Einkommensteuersatz und den jahrzehntelangen Zinseszinseffekt wächst das Endvermögen um sechsstellige Zusatzbeträge."
  },
  ja: {
    "How is a mortgage payment calculated?": "住宅ローンの毎月の返済額はどのように計算されますか？",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "一般的な毎月の返済額は元利均等返済（元金＋利息）、固定資産税、火災・地震保険料、保証料等で構成されます。",
    "What is the Debt Snowball method?": "スノーボール返済方式とは何ですか？",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "金利の高低にかかわらず借入残高が小さいものから完済し、早期の達成感を得る返済戦略です。",
    "What is the Debt Avalanche method?": "アバランチ返済方式とは何ですか？",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "金利（実質年率）が最も高い借入から優先的に返済し、総支払利息を最小化する戦略です。",
    "What is net worth?": "純資産（Net Worth）とは何ですか？",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "保有するすべての資産（預貯金・不動産・株式等）から負債（各種ローン）を差し引いた実質的な純価値です。",
    "How much emergency fund is recommended?": "生活防衛資金はいくら用意すべきですか？",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "一般的には毎月の固定生活費の3〜6ヶ月分、個人事業主なら9〜12ヶ月分の確保が推奨されます。",
    "What is Dollar-Cost Averaging (DCA)?": "ドルコスト平均法とは何ですか？",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "相場の変動に関わらず、毎月一定額を定期的に買い続けることで平均購入単価を平準化する手法です。",
    "What is inflation?": "インフレーション（物価上昇）とは何ですか？",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "モノやサービスの価格が全体的に上昇し、お金の購買力が相対的に低下する現象です。"
  },
  fr: {
    "How is a mortgage payment calculated?": "Comment est calculée la mensualité d'un prêt immobilier ?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "Une mensualité standard comprend le remboursement du capital, les intérêts bancaires, l'assurance emprunteur et les taxes afférentes.",
    "What is the Debt Snowball method?": "Qu'est-ce que la méthode Boule de Neige ?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Elle consiste à rembourser les dettes du plus petit montant au plus grand pour créer un déclic psychologique valorisant.",
    "What is the Debt Avalanche method?": "Qu'est-ce que la méthode Avalanche ?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Elle cible en priorité les crédits aux taux les plus élevés afin de minimiser le coût global des intérêts.",
    "What is net worth?": "Qu'est-ce que le patrimoine net ?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "C'est la différence entre la valeur totale de vos actifs (biens, épargne) et vos dettes cumulées.",
    "How much emergency fund is recommended?": "Quel montant prévoir pour son épargne de précaution ?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "Il est recommandé de conserver l'équivalent de 3 à 6 mois de dépenses courantes sur un compte immédiatement disponible.",
    "What is Dollar-Cost Averaging (DCA)?": "Qu'est-ce que l'investissement programmé (DCA) ?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "C'est la pratique consistant à investir une somme fixe à intervalles réguliers pour lisser le coût d'achat moyen.",
    "What is inflation?": "Qu'est-ce que l'inflation ?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "C'est la hausse durable du niveau général des prix entraînant la perte de pouvoir d'achat de la monnaie.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "Un prêt immobilier sur 15 ans offre généralement un taux d'intérêt plus bas et vous permet de rembourser votre logement deux fois plus vite, ce qui vous fait économiser des dizaines de milliers d'euros d'intérêts. Un prêt sur 30 ans implique toutefois des mensualités plus faibles, ce qui vous laisse une plus grande souplesse de trésorerie et rend le logement plus abordable au quotidien.",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Selon les standards australiens de retraite (norme ASFA), une personne seule a besoin d'une épargne retraite d'environ 595 000 € à 67 ans, tandis qu'un couple doit disposer d'environ 690 000 € pour maintenir un niveau de vie confortable à la retraite.",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "Le ratio de frais (expense ratio) correspond aux frais annuels prélevés par un fonds commun de placement ou un ETF pour sa gestion. Il s'exprime en pourcentage de votre investissement total (par exemple, 0,10 % représente 1 € par an pour 1 000 € investis).",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Tout versement supplémentaire sur votre prêt immobilier est imputé directement sur le capital restant dû. Cela réduit le solde du prêt et le montant des intérêts accumulés, vous permettant de solder votre crédit avec des années d'avance et d'économiser un montant considérable en intérêts.",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "La demande d'un nouveau prêt entraîne une légère baisse temporaire de votre score de crédit (5 à 10 points) liée à la vérification du dossier. Toutefois, utiliser ce prêt pour solder vos cartes de crédit saturées fait chuter immédiatement votre taux d'utilisation du crédit, ce qui améliore généralement votre score de façon significative sous 30 à 60 jours.",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "Le bêta mesure la volatilité ou le risque systématique d'un actif par rapport au marché global. Un bêta de 1,0 signifie que le cours évolue au même rythme que le marché. Un bêta supérieur à 1,0 indique une volatilité plus forte (risque et rendement potentiels accrus), tandis qu'un bêta inférieur à 1,0 signale une volatilité plus faible.",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "Le TCAC (taux de croissance annuel composé, ou CAGR en anglais) représente le taux de rendement annualisé de votre investissement sur une période de détention, en supposant que les gains sont capitalisés chaque année.",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "Le MEDAF (modèle d'évaluation des actifs financiers, ou CAPM en anglais) est un modèle financier qui calcule le rendement attendu d'un investissement en fonction de son risque systématique (bêta). Il sert de référence pour déterminer le coût des fonds propres.",
    "Can I do a hybrid of Snowball and Avalanche?": "Puis-je combiner les méthodes Boule de Neige et Avalanche ?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "Les versements à fiscalité avantageuse (y compris la cotisation patronale obligatoire et l'épargne salariale avant impôt) sont taxés à seulement 15 % au sein du fonds, contre une tranche marginale d'impôt sur le revenu pouvant atteindre 45 % hors prélèvements sociaux.",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "Les intérêts composés quotidiens sont calculés et crédités sur votre solde chaque jour (365 fois par an). Les jours suivants, vous percevez des intérêts à la fois sur votre capital initial et sur les intérêts déjà accumulés, ce qui accélère la croissance exponentielle de votre patrimoine.",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "Le regroupement de crédits réunit plusieurs dettes à taux élevés (comme des cartes de crédit à 20 %–29 % de TAEG) en un seul prêt personnel à taux fixe plus bas (par exemple 8 %–14 % de TAEG). Cela réduit votre mensualité totale et vous fait économiser des milliers d'euros en intérêts.",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "Le regroupement de crédits solde intégralement vos créanciers grâce à un nouveau prêt à taux réduit, sans dégrader votre historique de crédit. La négociation de dettes (debt settlement) consiste à cesser vos paiements pour négocier un montant inférieur à ce que vous devez, ce qui endommage gravement et durablement votre dossier de crédit.",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "Le revenu discrétionnaire correspond à la différence entre votre revenu brut ajusté et un pourcentage du seuil fédéral de pauvreté selon la taille de votre foyer (150 % pour les plans PAYE/IBR, 225 % pour le plan SAVE).",
    "Do high-yield savings accounts (HYSA) compound daily?": "Les comptes d'épargne à haut rendement composent-ils les intérêts quotidiennement ?",
    "Does debt consolidation hurt your credit score?": "Le regroupement de crédits nuit-il à votre score de crédit ?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE signifie Indépendance Financière, Retraite Anticipée (Financial Independence, Retire Early). C'est une stratégie qui consiste à maximiser votre taux d'épargne (souvent 40 % à 70 % des revenus) et à investir dans des fonds indiciels à faibles frais jusqu'à ce que votre portefeuille génère suffisamment de revenus passifs pour couvrir durablement vos dépenses.",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Pour toute personne née en 1960 ou après, l'âge légal de départ à taux plein est de 67 ans. Si vous partez à cet âge, vous percevez 100 % de votre pension de base, sans décote pour départ anticipé.",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Pour chaque année où vous différez votre départ au-delà de l'âge du taux plein (jusqu'à 70 ans), votre pension augmente de 8 % par an grâce aux majorations pour report. Attendre 70 ans vous garantit environ 124 % de votre pension à taux plein, à vie.",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "Le taux d'endettement immobilier (front-end) mesure uniquement la part du revenu brut mensuel consacrée au logement : mensualités du prêt, taxes foncières, assurance habitation et charges de copropriété. Le taux d'endettement global (back-end) inclut le logement plus toutes vos autres dettes mensuelles récurrentes : prêts étudiants, cartes de crédit, crédit auto et prêts personnels.",
    "How can I lower my Debt-to-Income ratio?": "Comment puis-je réduire mon taux d'endettement ?",
    "How do I calculate my refinance break-even point?": "Comment calculer le seuil de rentabilité de mon rachat de crédit ?",
    "How do I calculate stock returns?": "Comment calculer la rentabilité de vos actions ?",
    "How do extra payments affect my mortgage payoff schedule?": "Comment les versements supplémentaires affectent-ils votre calendrier de remboursement ?",
    "How does DTI affect my mortgage application?": "Comment le taux d'endettement influence-t-il votre demande de prêt immobilier ?",
    "How does debt consolidation save you money?": "Comment le regroupement de crédits vous fait-il économiser ?",
    "How does salary sacrificing boost superannuation growth?": "Comment l'épargne salariale avant impôt accélère-t-elle la croissance de votre retraite ?",
    "How does the 'extra payment' roll over in these strategies?": "Comment le versement supplémentaire est-il reporté dans ces stratégies ?",
    "How is discretionary income calculated for student loans?": "Comment le revenu discrétionnaire est-il calculé pour les prêts étudiants ?",
    "How is money inside Australian Super taxed?": "Comment l'épargne placée dans un fonds Super australien est-elle taxée ?",
    "How is your FIRE Number calculated?": "Comment votre objectif FIRE est-il calculé ?",
    "How much more do I get if I delay claiming Social Security until age 70?": "Combien gagnez-vous de plus en différant votre pension jusqu'à 70 ans ?",
    "How much more money do you earn with daily vs monthly compounding?": "Combien gagnez-vous de plus avec une capitalisation quotidienne plutôt que mensuelle ?",
    "How much super do I need for a comfortable retirement in Australia?": "De quelle épargne retraite avez-vous besoin pour une retraite confortable en Australie ?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Dans les deux méthodes, vous continuez à régler les mensualités minimales de toutes vos dettes. Toute somme supplémentaire disponible est affectée à la dette prioritaire (le plus petit solde ou le taux le plus élevé). Une fois cette dette soldée, vous reportez l'intégralité de sa mensualité (minimum + supplément) sur la dette suivante de votre liste.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "Un prêt sur 15 ans est-il préférable à un prêt sur 30 ans ?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Il est généralement judicieux de renégocier votre crédit si vous pouvez obtenir un taux plus bas, réduire votre mensualité ou raccourcir votre durée. L'objectif principal est de vous assurer que vos économies totales d'intérêts dépassent les frais de dossier et de clôture.",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Le Lean FIRE vise à couvrir uniquement des dépenses essentielles et minimalistes (généralement moins de 40 000 € par an). Le Standard FIRE maintient un mode de vie confortable de classe moyenne (50 000 € à 100 000 € par an). Le Fat FIRE permet des dépenses abondantes et luxueuses (plus de 120 000 € par an) sans contrainte financière.",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Les banques utilisent le taux d'endettement pour évaluer votre capacité à assumer vos mensualités. Un taux élevé signale un risque de surendettement, ce qui peut entraîner un refus ou des taux plus élevés. Un taux inférieur à 36 % est considéré comme un faible risque.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Mathématiquement, la méthode Avalanche est supérieure car elle minimise le total des intérêts payés. Toutefois, les études montrent que la méthode Boule de Neige réussit plus souvent en pratique, car la dynamique psychologique de solder rapidement des comptes aide à rester motivé et fidèle à votre plan.",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "Sur un dépôt de 100 000 € à 7 % de TAEG pendant 20 ans, la capitalisation quotidienne rapporte 405 514 € contre 403 873 € pour la capitalisation mensuelle, soit 1 641 € supplémentaires grâce à la seule fréquence de capitalisation.",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Issue de la célèbre étude Trinity, la règle des 4 % stipule que vous pouvez retirer 4 % de votre portefeuille initial chaque année (ajusté annuellement de l'inflation) avec plus de 95 % de probabilité de ne jamais épuiser votre capital pendant une retraite de 30 ans.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI signifie Capital, Intérêts, Taxes et Assurance. Ce sont les quatre composantes de base de la mensualité d'un propriétaire. Ensemble, elles reflètent le coût réel de la propriété mois après mois.",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "L'assurance emprunteur (PMI en anglais) est une garantie qui protège le prêteur en cas de défaut de paiement. Elle est généralement exigée pour les prêts classiques lorsque votre apport initial est inférieur à 20 % du prix d'achat du logement.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Les frais de rachat de crédit comprennent généralement les frais de dossier, les commissions de montage, les frais d'expertise, la recherche de titre et l'assurance associée, les frais de dossier de crédit et les frais d'enregistrement. Ils représentent entre 2 % et 6 % du montant du prêt.",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "L'épargne salariale avant impôt vous permet de verser une partie de votre salaire brut directement dans votre fonds de retraite. Comme vous évitez votre tranche marginale d'imposition plus élevée et profitez des intérêts composés pendant des décennies, ces versements supplémentaires peuvent ajouter des centaines de milliers d'euros à votre capital retraite.",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "La règle des 28/36 est une norme classique d'octroi des prêts immobiliers. Elle recommande de consacrer au maximum 28 % du revenu brut mensuel aux dépenses de logement, et au maximum 36 % à l'ensemble des remboursements de dettes (logement, cartes de crédit, crédit auto et prêts étudiants).",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "Le plan SAVE (Saving on a Valuable Education) est le plus récent dispositif de remboursement indexé sur les revenus. Il porte la part protégée du revenu à 225 % du seuil de pauvreté, abaisse les mensualités à 5 % du revenu discrétionnaire pour les prêts de premier cycle universitaire et empêche l'accumulation des intérêts impayés.",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "L'âge d'équilibre se situe généralement entre 78 et 81 ans. Si vous pensez vivre au-delà de 80 ans, différer votre départ jusqu'à 70 ans rapporte presque toujours un montant cumulé plus élevé sur l'ensemble de votre vie.",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "La formule de capitalisation quotidienne est A = P(1 + r/365)^(365 * t), où P est le capital initial, r le taux d'intérêt annuel (en décimal) et t la durée en années. Lorsque des versements réguliers sont ajoutés, les intérêts sont calculés sur le solde quotidien actualisé.",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Pour calculer la rentabilité totale d'une action, soustrayez le prix d'achat du prix de vente pour obtenir la plus-value. Ajoutez les dividendes perçus. Divisez cette somme par le prix d'achat initial, puis multipliez par 100 pour obtenir le rendement en pourcentage.",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Pour trouver votre seuil de rentabilité, divisez le total de vos frais de rachat par l'économie mensuelle réalisée. Par exemple, avec 3 000 € de frais et 150 € d'économie par mois, votre seuil est atteint en 20 mois (3 000 € / 150 €). Si vous prévoyez de vendre ou de déménager avant ce délai, le rachat risque de ne pas être financièrement judicieux.",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "Les versements sur un compte de retraite traditionnel (Traditional IRA) sont généralement effectués avant impôt (réduisant votre revenu imposable actuel), mais les retraits à la retraite sont imposés comme des revenus ordinaires. Les versements sur un compte Roth IRA sont effectués avec des fonds déjà imposés ; la croissance et les retraits à la retraite sont totalement exonérés d'impôt.",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "En vertu de la législation fédérale australienne, les employeurs sont tenus de verser un pourcentage de votre salaire ordinaire dans votre fonds de retraite désigné. Ce taux doit atteindre 12 % selon la loi en vigueur.",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Méfiez-vous des frais de montage (généralement 1 % à 6 % du montant du prêt), assurez-vous que la nouvelle mensualité s'intègre confortablement dans votre budget et évitez de creuser de nouveaux soldes sur les cartes de crédit que vous venez de solder.",
    "What closing costs are associated with refinancing?": "Quels frais de clôture sont liés à un rachat de crédit ?",
    "What does Asset Beta (β) represent?": "Que représente le bêta (β) d'un actif ?",
    "What does PITI stand for?": "Que signifie le sigle PITI ?",
    "What is CAGR in stock returns?": "Qu'est-ce que le TCAC (CAGR) en matière d'actions ?",
    "What is PMI and when do I pay it?": "Qu'est-ce que l'assurance emprunteur (PMI) et quand la payez-vous ?",
    "What is an expense ratio?": "Qu'est-ce que le ratio de frais ?",
    "What is daily compound interest and how does it work?": "Qu'est-ce que les intérêts composés quotidiens et comment fonctionnent-ils ?",
    "What is my Full Retirement Age (FRA)?": "Quel est mon âge de départ à taux plein ?",
    "What is the 28/36 rule?": "Qu'est-ce que la règle des 28/36 ?",
    "What is the 4% Safe Withdrawal Rule?": "Qu'est-ce que la règle des 4 % de retrait sans risque ?",
    "What is the Australian Superannuation Guarantee (SG) rate?": "Quel est le taux de la garantie de retraite obligatoire australienne (SG) ?",
    "What is the Capital Asset Pricing Model (CAPM)?": "Qu'est-ce que le modèle d'évaluation des actifs financiers (MEDAF / CAPM) ?",
    "What is the FIRE movement and what does it mean?": "Qu'est-ce que le mouvement FIRE et que signifie-t-il ?",
    "What is the SAVE plan?": "Qu'est-ce que le plan SAVE ?",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "Quel est l'âge d'équilibre entre un départ à 62 ans ou à 70 ans ?",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Quelle est la différence entre le Lean FIRE, le Standard FIRE et le Fat FIRE ?",
    "What is the difference between debt consolidation and debt settlement?": "Quelle est la différence entre le regroupement de crédits et la négociation de dettes ?",
    "What is the difference between front-end and back-end DTI?": "Quelle est la différence entre le taux d'endettement immobilier et le taux global ?",
    "What is the formula for daily compound interest?": "Quelle est la formule des intérêts composés quotidiens ?",
    "What is the key difference between a Roth and Traditional IRA?": "Quelle est la différence clé entre un compte Roth IRA et un compte traditionnel ?",
    "What should I look out for before consolidating debt?": "À quoi devez-vous faire attention avant de regrouper vos crédits ?",
    "When is the earliest age I can claim Social Security retirement benefits?": "Quel est l'âge minimal pour demander votre pension de retraite ?",
    "When should I refinance my loan?": "Quand devriez-vous renégocier votre prêt ?",
    "Which method is better: Debt Snowball or Debt Avalanche?": "Quelle méthode est préférable : Boule de Neige ou Avalanche ?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Oui, la grande majorité des comptes d'épargne à haut rendement et des comptes monétaires composent les intérêts quotidiennement et les créditent sur votre solde le dernier jour ouvré du mois.",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Oui. Certaines personnes préfèrent solder une ou deux petites dettes d'abord pour constater un progrès immédiat et libérer de la trésorerie (Boule de Neige), puis s'attaquer aux dettes restantes en commençant par les taux les plus élevés pour économiser sur les intérêts (Avalanche).",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Vous pouvez réduire votre taux d'endettement en augmentant votre revenu brut mensuel (par exemple en obtenant une augmentation ou en lançant une activité complémentaire) ou en remboursant vos dettes récurrentes. Concentrez-vous sur le remboursement intégral des petits prêts pour éliminer leur mensualité minimale de votre calcul d'endettement.",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "Vous pouvez commencer à percevoir votre pension de retraite dès 62 ans. Toutefois, un départ anticipé réduit définitivement votre mensualité jusqu'à 30 % par rapport à un départ à l'âge du taux plein.",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Votre objectif FIRE correspond à vos dépenses annuelles multipliées par 25 (selon la règle des 4 %) ou par 33 (selon une règle prudente de 3 %). Par exemple, si vous vivez confortablement avec 60 000 € par an, votre objectif FIRE est de 1 500 000 €."
  },
  pt: {
    "Front-end DTI only includes housing expenses (mortgage principal, interest, taxes, and insurance). Back-end DTI includes housing expenses plus all other recurring debts like student loans, auto loans, and minimum credit card payments.": "O DTI front-end (habitacional) inclui apenas despesas de moradia (amortização, juros da hipoteca, impostos e seguros). O DTI back-end (total) engloba os gastos com moradia mais todas as outras dívidas recorrentes, como financiamento estudantil, parcelas do carro e pagamento mínimo do cartão de crédito.",
    "You can lower your DTI by paying down outstanding credit card balances, paying off small personal loans, refinancing to lower rates, or increasing your gross monthly income (e.g. through a side business, raise, or adding a co-borrower).": "Você pode reduzir seu DTI amortizando saldos devedores de cartão de crédito, quitando pequenos empréstimos pessoais, refinanciando com taxas mais baixas ou aumentando sua renda bruta mensal (por exemplo, obtendo um aumento salarial, iniciando uma atividade extra ou incluindo um coobrigado/cônjuge no financiamento).",
    "By combining multiple high-interest credit card balances or personal loans into a single personal loan with a lower interest rate, you reduce the total amount of interest that accumulates each month. This lets more of your monthly payment go directly towards the principal balance.": "Ao unificar múltiplos saldos caros de cartão de crédito ou empréstimos pessoais em uma única linha de crédito com taxa de juros inferior, você reduz o volume de juros acumulados a cada mês. Isso permite que uma parcela maior do seu pagamento mensal seja direcionada para amortizar o saldo principal.",
    "Watch out for upfront origination fees, prepayment penalties, and ensure the new loan term isn't stretched so far out that you pay more total interest despite a lower monthly payment. Most importantly, avoid running up new balances on the cleared credit cards.": "Fique atento a tarifas iniciais de abertura de crédito, eventuais taxas de liquidação antecipada e certifique-se de que o novo prazo não seja excessivamente longo a ponto de gerar mais juros totais, mesmo com parcelas menores. Sobretudo, evite contrair novas dívidas nos cartões de crédito recém-quitados.",
    "The earliest age you can claim Social Security retirement benefits is 62. However, claiming early results in a permanent reduction of up to 30% of your monthly benefit compared to waiting until full retirement age.": "A idade mínima para solicitar a aposentadoria por idade é 62 anos. No entanto, a antecipação acarreta uma redução definitiva de até 30% no valor do benefício mensal em comparação com a espera até a idade plena de aposentadoria.",
    "For every year you delay claiming Social Security past your Full Retirement Age (up to age 70), your benefit increases by 8% per year in delayed retirement credits (up to a 24% permanent boost at age 70).": "Para cada ano em que você posterga a solicitação da aposentadoria além da sua Idade Plena (até os 70 anos), seu benefício recebe um bônus adicional de 8% ao ano (totalizando um acréscimo permanente de até 24% aos 70 anos).",
    "What is the Social Security break-even age between claiming early vs delaying?": "Qual é a idade de equilíbrio entre solicitar a aposentadoria antecipada ou adiar o benefício?",
    "The break-even age between claiming early at age 62 versus waiting until age 70 is typically around age 80 to 82. If you expect to live past this age, waiting until 70 produces significantly more lifetime wealth.": "A idade de equilíbrio entre se aposentar antecipadamente aos 62 anos ou aguardar até os 70 anos situa-se normalmente entre 80 e 82 anos de idade. Se a sua expectativa de vida superar esse patamar, esperar até os 70 anos proporciona um patrimônio acumulado consideravelmente maior ao longo da vida.",
    "Under Australian law, employers are required to contribute a statutory percentage of your ordinary time earnings into your superannuation fund. The rate is legislated to increase progressively to 12%.": "Pela legislação australiana, os empregadores são obrigados a recolher um percentual compulsório sobre a remuneração normal do trabalhador para o fundo de aposentadoria (Superannuation). A alíquota está estipulada em lei para alcançar progressivamente 12%.",
    "FIRE stands for Financial Independence, Retire Early. It is a financial movement dedicated to extreme savings and intentional investing, allowing people to retire decades before conventional retirement ages.": "FIRE é a sigla em inglês para Independência Financeira e Aposentadoria Precoce (Financial Independence, Retire Early). Trata-se de um movimento financeiro focado em alta taxa de poupança e investimentos estratégicos, possibilitando que pessoas se aposentem décadas antes da idade convencional.",
    "The 4% Rule, established by the Trinity Study, states that you can safely withdraw 4% of your invested portfolio in the first year of retirement, adjust that dollar amount for inflation every year thereafter, and have a 95%+ probability of your money lasting 30+ years.": "A Regra dos 4%, fundamentada pelo consagrado Estudo de Trinity, determina que você pode resgatar com segurança 4% da sua carteira investida no primeiro ano de aposentadoria, reajustando esse montante pela inflação a cada ano subsequente, mantendo mais de 95% de probabilidade de que os recursos durem por 30 anos ou mais.",
    "Your FIRE Number is calculated by multiplying your estimated annual living expenses by 25 (the inverse of the 4% rule): Annual Expenses × 25 = FIRE Goal.": "O seu Número FIRE é calculado multiplicando suas despesas anuais de custo de vida estimadas por 25 (o inverso da regra dos 4%): Despesas Anuais × 25 = Meta de Patrimônio FIRE.",
    "Lean FIRE targets a minimalist lifestyle with expenses below average (usually under $40,000/year). Standard FIRE covers typical baseline middle-class expenses ($40,000–$80,000/year). Fat FIRE supports an affluent lifestyle with abundant travel and luxury ($100,000+/year).": "O Lean FIRE tem como meta um estilo de vida minimalista com despesas abaixo da média (geralmente abaixo de R$ 100 mil a R$ 150 mil anuais / US$ 40 mil). O Standard FIRE cobre um padrão confortável de classe média. Já o Fat FIRE sustenta um estilo de vida mais abastado, com viagens frequentes e maior margem para supérfluos.",
    "Daily compound interest calculates interest on both your initial principal and previously accumulated interest each day. Over time, interest begins earning interest rapidly, creating an exponential curve that grows significantly faster than simple or monthly compounding.": "Os juros compostos diários calculam o rendimento a cada dia tanto sobre o principal inicial quanto sobre os juros acumulados anteriormente. Com o passar do tempo, os juros geram novos juros de forma acelerada, formando uma curva exponencial que supera com folga a capitalização simples ou mensal.",
    "The standard daily compounding formula is A = P(1 + r/365)^(365*t), where A is the final balance, P is initial principal, r is annual interest rate (decimal), and t is time in years.": "A fórmula padrão da capitalização diária é M = C(1 + i/365)^(365*t), onde M é o montante final, C é o capital inicial, i é a taxa de juros anual (em formato decimal) e t é o tempo em anos.",
    "On a $100,000 deposit at 5% APY over 20 years, daily compounding yields roughly $300 to $500 more than monthly compounding due to faster compounding reinvestment.": "Em uma aplicação de R$ 100.000 / US$ 100.000 a 5% ao ano por 20 anos, a capitalização diária rende cerca de R$ 300 a R$ 500 a mais do que a capitalização mensal em virtude do reinvestimento mais imediato dos juros.",
    "Yes! Most modern high-yield savings accounts and money market accounts compound interest daily and credit the earnings into your account on a monthly basis.": "Sim! A maioria das contas remuneradas modernas, fundos de liquidez diária e CDBs/contas de alto rendimento calcula juros compostos diariamente e credita os proventos na conta mensalmente.",
    "What is an HP 12C financial calculator and why is it used?": "O que é a calculadora financeira HP 12C e por que ela é tão utilizada?",
    "The HP 12C is the gold standard programmable financial calculator created by Hewlett-Packard in 1981. It is renowned for its durability, Reverse Polish Notation (RPN) efficiency, and is one of the few calculators permitted on the CFA, CFP, and Real Estate appraiser certification examinations.": "A HP 12C é o padrão ouro entre as calculadoras financeiras programáveis, lançada pela Hewlett-Packard em 1981. É reconhecida por sua extrema durabilidade, rapidez com Notação Polonesa Reversa (RPN) e é uma das raras calculadoras autorizadas nos exames oficiais de certificação CFA, CFP e perícia imobiliária.",
    "How does Reverse Polish Notation (RPN) work on the HP 12C?": "Como funciona a Notação Polonesa Reversa (RPN) na HP 12C?",
    "RPN eliminates the need for parentheses and an equals key. You enter numbers first onto a 4-level stack (X, Y, Z, T), and then press the operator. For example, to add 25 and 15, you press [2][5] [ENTER] [1][5] [+], giving 40 immediately.": "O sistema RPN elimina a necessidade de parênteses e da tecla de igual. Você insere primeiro os números em uma pilha operacional de 4 níveis (X, Y, Z, T) e depois pressiona o operador desejado. Por exemplo, para somar 25 e 15, você digita [2][5] [ENTER] [1][5] [+], obtendo 40 instantaneamente.",
    "How do I calculate Time Value of Money (TVM) on this emulator?": "Como calculo o Valor do Dinheiro no Tempo (TVM) neste emulador?",
    "Store your known values into the TVM registers (n for periods, i for interest rate, PV for present value, PMT for payment, FV for future value). Press the key of the unknown variable to solve for it. Remember financial sign conventions: cash outflows are entered with CHS (negative).": "Armazene os valores conhecidos nos registradores de TVM (n para prazos, i para taxa de juros, PV para valor presente, PMT para parcelas, FV para valor futuro). Pressione a tecla da variável que deseja descobrir. Lembre-se da convenção de sinais financeiros: saídas de caixa devem ser inseridas com sinal negativo usando a tecla CHS.",
    "Can I use my physical computer keyboard with this emulator?": "Posso usar o teclado físico do meu computador com este emulador?",
    "Yes! Use your computer numpad or number keys for digits 0-9, Enter for the ENTER stack key, standard arithmetic keys (+, -, *, /), and Backspace to clear the entry.": "Sim! Utilize o teclado numérico ou as teclas de 0 a 9 do teclado, a tecla Enter para a função ENTER da pilha, as operações aritméticas normais (+, -, *, /) e o Backspace para apagar a digitação.",
    "Is the TI BA II Plus permitted on CFA and CFP exams?": "A calculadora TI BA II Plus é permitida nos exames CFA e CFP?",
    "Yes! The Texas Instruments BA II Plus (including the Professional model) is one of only two official calculators authorized by the CFA Institute, GARP (FRM), and CFP Board for in-person certification examinations.": "Sim! A Texas Instruments BA II Plus (incluindo o modelo Professional) é uma das duas únicas calculadoras oficiais homologadas pelo CFA Institute, GARP (FRM) e CFP Board para exames presenciais de certificação.",
    "How do I solve for a TVM variable (like PV or PMT) on the TI BA II Plus?": "Como calculo uma variável de TVM (como PV ou PMT) na TI BA II Plus?",
    "Enter your known values by typing the number followed by the variable key (e.g., [1][0] [N], [8] [I/Y], [5][0][0] [CHS] [PMT]). To calculate the unknown value, press [CPT] followed by the variable key (e.g., [CPT] [PV]).": "Insira seus valores conhecidos digitando o número seguido da tecla da respectiva variável (ex: [1][0] [N], [8] [I/Y], [5][0][0] [CHS] [PMT]). Para calcular a incógnita, pressione [CPT] seguido da tecla da variável desejada (ex: [CPT] [PV]).",
    "What is the difference between BGN and END mode?": "Qual é a diferença entre o modo BGN e o modo END?",
    "END mode assumes cash flows occur at the end of each payment period (standard loans, ordinary annuities). BGN mode assumes payments occur at the beginning of each period (annuities due, lease payments).": "O modo END assume que as parcelas e fluxos ocorrem ao final de cada período (financiamentos tradicionais e anuidades postecipadas). O modo BGN assume pagamentos no início de cada período (anuidades antecipadas, aluguéis e contratos de leasing).",
    "Why does my answer have a negative sign?": "Por que o resultado do meu cálculo aparece com sinal negativo?",
    "Financial calculators strictly enforce cash flow conventions. Money paid out (outflow/deposit/investment) is negative; money received (inflow/loan proceeds/future payout) is positive.": "As calculadoras financeiras aplicam com rigor a convenção de fluxo de caixa. O dinheiro desembolsado (saída, aporte, investimento ou pagamento de parcela) é registrado como negativo; o dinheiro recebido (entrada, liberação do empréstimo ou resgate futuro) é registrado como positivo.",
    "How is a mortgage payment calculated?": "Como é calculada a parcela do financiamento imobiliário?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "A parcela mensal é formada por amortização do principal, juros contratuais, taxa de administração e seguros obrigatórios (MIP/DFI).",
    "What is the Debt Snowball method?": "O que é o método Bola de Neve?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Consiste em pagar primeiro as dívidas de menor saldo devedor, gerando vitórias rápidas e estímulo comportamental.",
    "What is the Debt Avalanche method?": "O que é o método Avalanche?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Consiste em quitar prioritariamente as dívidas com a maior taxa de juros, minimizando o custo total.",
    "What is net worth?": "O que é patrimônio líquido?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "É o valor total de todos os seus bens e investimentos (ativos) menos todas as suas dívidas e obrigações (passivos).",
    "How much emergency fund is recommended?": "Qual o valor ideal para a reserva de emergência?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "Recomenda-se guardar entre 3 e 6 meses de despesas básicas em aplicações de liquidez diária e baixo risco.",
    "What is Dollar-Cost Averaging (DCA)?": "O que é a estratégia Dollar-Cost Averaging (DCA)?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "É a aplicação periódica de quantias fixas (mensais), diluindo o preço médio de compra e reduzindo o risco de oscilações.",
    "What is inflation?": "O que é inflação?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "É o aumento generalizado e contínuo dos preços, que resulta na perda do poder de compra da moeda.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "Um financiamento de 15 anos costuma oferecer juros menores e permite quitar o imóvel na metade do tempo, economizando dezenas de milhares de reais em juros. Já o prazo de 30 anos tem parcelas menores, o que dá mais folga ao fluxo de caixa e torna o imóvel mais acessível no mês a mês.",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Segundo o padrão de aposentadoria da ASFA, uma pessoa solteira precisa de um saldo de aproximadamente R$ 595.000 aos 67 anos, enquanto um casal precisa de cerca de R$ 690.000 para manter um padrão de vida confortável na aposentadoria.",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "A taxa de administração é a tarifa anual cobrada por um fundo de investimento ou ETF para gerir o fundo. Ela é expressa como um percentual do seu investimento total (por exemplo, 0,10% significa R$ 1 por ano para cada R$ 1.000 investidos).",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Todo valor extra que você paga no financiamento é abatido diretamente do saldo devedor. Isso reduz o saldo restante e diminui os juros acumulados, ajudando você a quitar o imóvel anos antes do prazo e economizando uma quantia considerável em juros.",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "Solicitar um novo empréstimo causa uma pequena queda temporária (de 5 a 10 pontos) por causa da consulta ao seu crédito. No entanto, usar o empréstimo para quitar cartões de crédito no limite reduz imediatamente sua taxa de utilização do crédito, o que costuma aumentar bastante sua pontuação em 30 a 60 dias.",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "O Beta mede a volatilidade ou o risco sistemático de um ativo em relação ao mercado como um todo. Um Beta de 1,0 indica que o preço acompanha o mercado. Beta acima de 1,0 significa maior volatilidade (mais risco e retorno potencial), enquanto Beta abaixo de 1,0 significa menor volatilidade.",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "CAGR é a sigla para Taxa de Crescimento Anual Composta. Ela representa o retorno anualizado do seu investimento ao longo de um período, considerando que os ganhos foram reinvestidos a cada ano.",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "O CAPM é um modelo financeiro que calcula o retorno esperado de um investimento ou ativo com base no seu nível de risco sistemático (Beta). Ele serve de base para determinar o custo do capital próprio.",
    "Can I do a hybrid of Snowball and Avalanche?": "Posso combinar os métodos Bola de Neve e Avalanche?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "As contribuições com incentivo fiscal (incluindo a contribuição patronal obrigatória e aportes via salário antes dos impostos) são tributadas a apenas 15% dentro do fundo, enquanto sua faixa marginal de imposto de renda pode chegar a 45% mais a taxa do Medicare.",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "Os juros compostos diários calculam e creditam os juros ganhos no seu saldo todos os dias (365 vezes por ano). Nos dias seguintes, você ganha juros tanto sobre o capital inicial quanto sobre os juros já acumulados, acelerando o crescimento exponencial do patrimônio.",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "A consolidação de dívidas reúne várias dívidas com juros altos (como cartões de crédito com CET de 20% a 29%) em um único empréstimo pessoal com taxa fixa menor (por exemplo, CET de 8% a 14%). Isso reduz sua parcela mensal total e economiza milhares de reais em juros.",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "A consolidação de dívidas quita integralmente seus credores por meio de um novo empréstimo com taxa menor, sem prejudicar seu histórico de crédito. Já a renegociação com desconto envolve parar de pagar e negociar um valor menor do que você deve, o que causa danos graves e duradouros ao seu histórico de crédito.",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "A renda discricionária é a diferença entre sua renda bruta ajustada e um percentual da linha federal de pobreza para o tamanho da sua família (150% para PAYE/IBR e 225% para SAVE).",
    "Do high-yield savings accounts (HYSA) compound daily?": "As contas de poupança de alto rendimento rendem juros compostos diários?",
    "Does debt consolidation hurt your credit score?": "Consolidar dívidas prejudica sua pontuação de crédito?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE significa Independência Financeira, Aposentadoria Antecipada. É uma estratégia em que você maximiza sua taxa de poupança (geralmente de 40% a 70% da renda) e investe em fundos de índice baratos até que a carteira gere renda passiva suficiente para cobrir seus gastos para sempre.",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Para quem nasceu em 1960 ou depois, a idade plena de aposentadoria é 67 anos. Se você se aposentar nessa idade, recebe 100% do benefício-base sem penalidades por antecipação.",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Para cada ano que você adia a aposentadoria após a idade plena (até os 70 anos), seu benefício aumenta 8% ao ano por meio de créditos por adiamento. Esperar até os 70 anos garante cerca de 124% do benefício integral pelo resto da vida.",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "O comprometimento de renda com moradia considera apenas o percentual da renda bruta mensal gasto com habitação, como parcelas do financiamento, IPTU, seguro residencial e taxa de condomínio. Já o comprometimento total inclui a moradia mais todas as outras dívidas mensais recorrentes, como financiamento estudantil, cartões de crédito, prestações do carro e empréstimos pessoais.",
    "How can I lower my Debt-to-Income ratio?": "Como posso reduzir meu comprometimento de renda?",
    "How do I calculate my refinance break-even point?": "Como calculo o ponto de equilíbrio do refinanciamento?",
    "How do I calculate stock returns?": "Como calculo o retorno das minhas ações?",
    "How do extra payments affect my mortgage payoff schedule?": "Como os pagamentos extras afetam meu cronograma de quitação do financiamento?",
    "How does DTI affect my mortgage application?": "Como o comprometimento de renda afeta meu pedido de financiamento?",
    "How does debt consolidation save you money?": "Como a consolidação de dívidas economiza seu dinheiro?",
    "How does salary sacrificing boost superannuation growth?": "Como o aporte via salário aumenta o crescimento da aposentadoria?",
    "How does the 'extra payment' roll over in these strategies?": "Como o “pagamento extra” é transferido nessas estratégias?",
    "How is discretionary income calculated for student loans?": "Como a renda discricionária é calculada para financiamentos estudantis?",
    "How is money inside Australian Super taxed?": "Como o dinheiro dentro do Super australiano é tributado?",
    "How is your FIRE Number calculated?": "Como seu Número FIRE é calculado?",
    "How much more do I get if I delay claiming Social Security until age 70?": "Quanto a mais recebo se adiar minha aposentadoria até os 70 anos?",
    "How much more money do you earn with daily vs monthly compounding?": "Quanto a mais você ganha com capitalização diária em vez de mensal?",
    "How much super do I need for a comfortable retirement in Australia?": "De quanto preciso no Super para uma aposentadoria confortável na Austrália?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Nos dois métodos, você continua pagando o valor mínimo de todas as suas dívidas. Todo dinheiro extra que você conseguir é somado à parcela da dívida prioritária (o menor saldo ou os maiores juros). Quando essa dívida é quitada, você transfere toda a sua parcela mensal (mínimo + extra) para a próxima dívida da lista.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "Um financiamento de 15 anos é melhor do que um de 30 anos?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Geralmente vale a pena refinanciar se você conseguir uma taxa de juros menor, reduzir sua parcela mensal ou encurtar o prazo. O objetivo principal é garantir que a economia total em juros supere os custos de fechamento.",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "O Lean FIRE foca em cobrir apenas gastos essenciais e minimalistas (geralmente abaixo de R$ 40.000 por ano). O Standard FIRE mantém um padrão de vida confortável de classe média (R$ 50.000 a R$ 100.000 por ano). O Fat FIRE comporta gastos abundantes e luxuosos (acima de R$ 120.000 por ano) sem restrições financeiras.",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Os bancos usam o comprometimento de renda para avaliar sua capacidade de arcar com as parcelas. Um índice alto indica possível endividamento excessivo, o que pode levar à recusa ou a juros maiores. Índices abaixo de 36% são considerados de baixo risco.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Matematicamente, o método Avalanche é superior porque minimiza o total de juros pagos. No entanto, estudos mostram que o método Bola de Neve costuma ter mais sucesso na prática, porque o impulso psicológico de quitar contas individuais rapidamente ajuda você a se manter motivado e fiel ao plano.",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "Em um depósito de R$ 100.000 a 7% de CET ao ano por 20 anos, a capitalização diária rende R$ 405.514, contra R$ 403.873 da capitalização mensal — ou seja, R$ 1.641 a mais apenas pela frequência da capitalização.",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Originada no histórico Estudo Trinity, a regra dos 4% diz que você pode sacar 4% da sua carteira inicial de investimentos por ano (com correção anual pela inflação) com mais de 95% de probabilidade de nunca zerar seu patrimônio ao longo de uma aposentadoria de 30 anos.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI é a sigla para Principal, Juros, Impostos e Seguros. São os quatro componentes básicos da parcela mensal de quem tem casa própria. Juntos, eles refletem o custo real de manter um imóvel mês a mês.",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "O seguro prestamista é uma apólice que protege o banco caso você deixe de pagar. Ele costuma ser exigido em financiamentos convencionais quando a entrada é menor que 20% do valor do imóvel.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Os custos de refinanciamento geralmente incluem taxas de análise, taxa de abertura, custos de avaliação, pesquisa e seguro de escritura, taxa de consulta ao crédito e taxas de registro. Eles variam de 2% a 6% do valor do empréstimo.",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "O aporte via salário permite direcionar parte do salário bruto diretamente para a aposentadoria. Como você evita sua faixa mais alta de imposto e aproveita os juros compostos ao longo de décadas, essas contribuições extras podem somar centenas de milhares de reais ao seu saldo de aposentadoria.",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "A regra 28/36 é uma diretriz padrão de análise de crédito imobiliário. Ela diz que uma família deve gastar no máximo 28% da renda bruta mensal com moradia e no máximo 36% com o total de dívidas (incluindo moradia, cartões de crédito, carro e financiamento estudantil).",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "O plano SAVE (Saving on a Valuable Education) é o mais novo modelo de pagamento vinculado à renda. Ele eleva a faixa de renda protegida para 225% da linha de pobreza, reduz as parcelas para 5% da renda discricionária em empréstimos de graduação e impede o acúmulo de juros não pagos.",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "A idade de equilíbrio costuma ficar entre 78 e 81 anos. Se você espera viver além dos 80 anos, adiar a aposentadoria até os 70 anos quase sempre resulta em um valor total maior ao longo da vida.",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "A fórmula da capitalização diária é M = C(1 + i/365)^(365 × t), onde C é o capital inicial, i é a taxa anual de juros (em decimal) e t é o tempo em anos. Quando há depósitos recorrentes, os juros são calculados sobre o saldo diário atualizado.",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Para calcular o retorno total de uma ação, subtraia o preço de compra do preço de venda para achar o ganho de capital. Some os dividendos recebidos. Divida esse total pelo preço inicial de compra e multiplique por 100 para obter o retorno percentual.",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Para achar seu ponto de equilíbrio, divida o custo total de fechamento do refinanciamento pela economia mensal na parcela. Por exemplo, se os custos são R$ 3.000 e você economiza R$ 150 por mês, o ponto de equilíbrio é 20 meses (R$ 3.000 / R$ 150). Se você pretende vender ou se mudar antes disso, o refinanciamento pode não valer a pena.",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "As contribuições ao Traditional IRA geralmente são feitas antes dos impostos (reduzindo sua renda tributável atual), mas os saques na aposentadoria são tributados como renda comum. As contribuições ao Roth IRA são feitas com dinheiro já tributado; o crescimento e os saques na aposentadoria são totalmente isentos de imposto.",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "Pela lei federal australiana, os empregadores são obrigados a contribuir com um percentual dos seus ganhos regulares para o seu fundo de aposentadoria designado. A alíquota prevista em lei deve chegar a 12%.",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Atenção às taxas de abertura (geralmente de 1% a 6% do valor do empréstimo), garanta que a nova parcela caiba com folga no seu orçamento e evite acumular novos saldos nos cartões que você acabou de quitar.",
    "What closing costs are associated with refinancing?": "Quais custos de fechamento estão associados ao refinanciamento?",
    "What does Asset Beta (β) represent?": "O que o Beta (β) de um ativo representa?",
    "What does PITI stand for?": "O que significa a sigla PITI?",
    "What is CAGR in stock returns?": "O que é CAGR no retorno de ações?",
    "What is PMI and when do I pay it?": "O que é o seguro prestamista e quando eu o pago?",
    "What is an expense ratio?": "O que é taxa de administração?",
    "What is daily compound interest and how does it work?": "O que são juros compostos diários e como funcionam?",
    "What is my Full Retirement Age (FRA)?": "Qual é minha idade plena de aposentadoria?",
    "What is the 28/36 rule?": "O que é a regra 28/36?",
    "What is the 4% Safe Withdrawal Rule?": "O que é a regra dos 4% para saques seguros?",
    "What is the Australian Superannuation Guarantee (SG) rate?": "Qual é a alíquota da Garantia de Aposentadoria (SG) australiana?",
    "What is the Capital Asset Pricing Model (CAPM)?": "O que é o Modelo de Precificação de Ativos Financeiros (CAPM)?",
    "What is the FIRE movement and what does it mean?": "O que é o movimento FIRE e o que ele significa?",
    "What is the SAVE plan?": "O que é o plano SAVE?",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "Qual é a idade de equilíbrio entre pedir a aposentadoria aos 62 ou aos 70 anos?",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Qual é a diferença entre Lean FIRE, Standard FIRE e Fat FIRE?",
    "What is the difference between debt consolidation and debt settlement?": "Qual é a diferença entre consolidação e renegociação de dívidas com desconto?",
    "What is the difference between front-end and back-end DTI?": "Qual é a diferença entre comprometimento de renda com moradia e total?",
    "What is the formula for daily compound interest?": "Qual é a fórmula dos juros compostos diários?",
    "What is the key difference between a Roth and Traditional IRA?": "Qual é a principal diferença entre um Roth IRA e um Traditional IRA?",
    "What should I look out for before consolidating debt?": "Com o que devo tomar cuidado antes de consolidar dívidas?",
    "When is the earliest age I can claim Social Security retirement benefits?": "Qual é a idade mínima para pedir os benefícios de aposentadoria?",
    "When should I refinance my loan?": "Quando devo refinanciar meu empréstimo?",
    "Which method is better: Debt Snowball or Debt Avalanche?": "Qual método é melhor: Bola de Neve ou Avalanche?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Sim, a grande maioria das contas de poupança de alto rendimento e das contas do mercado monetário rende juros compostos diários e credita o valor no seu saldo no último dia útil do mês.",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Sim. Algumas pessoas preferem quitar uma ou duas dívidas pequenas primeiro para ver progresso imediato e liberar fluxo de caixa (Bola de Neve) e depois focar nas dívidas restantes pelos maiores juros para economizar nos juros (Avalanche).",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Você pode reduzir seu comprometimento de renda aumentando sua renda bruta mensal (por exemplo, conseguindo um aumento ou iniciando uma renda extra) ou quitando suas dívidas recorrentes. Concentre-se em quitar totalmente os empréstimos menores para eliminar a parcela mínima deles do cálculo.",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "Você pode começar a receber os benefícios de aposentadoria a partir dos 62 anos. No entanto, antecipar reduz permanentemente sua parcela mensal em até 30% em comparação com esperar até a idade plena de aposentadoria.",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Seu Número FIRE é seus gastos anuais multiplicados por 25 (pela regra dos 4%) ou por 33 (pela regra conservadora dos 3%). Por exemplo, se você vive confortavelmente com R$ 60.000 por ano, seu Número FIRE é R$ 1.500.000."
  },
};

// Merge allFaqs into faqTranslations
for (const lang of Object.keys(allFaqs) as Lang[]) {
  if (!faqTranslations[lang]) {
    faqTranslations[lang] = {};
  }
  if (allFaqs[lang]) {
    Object.assign(faqTranslations[lang], allFaqs[lang]);
  }
}

